def parse_range(s):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    if '-' in s:
        parts = s.split('-')
        if len(parts) != 2:
            raise ValueError("Invalid range format")
        try:
            start = int(parts[0])
            end = int(parts[1])
        except ValueError:
            raise ValueError("Invalid range format")
        if start > end:
            raise ValueError("Invalid range")
        return list(range(start, end + 1))
    else:
        try:
            num = int(s)
        except ValueError:
            raise ValueError("Invalid input")
        return [num]
